select drug_id,img ,drug_name as name, price, quantity, specifications, d.type_name as type, usage1, dosage, manufacturer, expiration_date, symptoms,d.create_time, d.update_time from drugs join drugs_relation d on drugs.type_id = d.type_id where d.relation_type = 1
ORDER BY ${orders}
ASC
DESC
limit #{size} offset #{offset}

select drug_id, drug_name as name, price, quantity, specifications, d.type_name as type, usage1, dosage, manufacturer, expiration_date, symptoms, notes,d.create_time, d.update_time from drugs join drugs_relation d on drugs.type_id = d.type_id where d.relation_type = 1 and drugs.drug_name like concat('%',#{name},'%')
ORDER BY ${orders}
ASC
DESC
limit #{size} offset #{offset}

select drug_id, drug_name as name, price, quantity, specifications, d.type_name as type, usage1, dosage, manufacturer, expiration_date, symptoms, notes,d.create_time, d.update_time from drugs join drugs_relation d on drugs.type_id = d.type_id where d.relation_type = 1 and drugs.drug_name like concat('%',#{type},'%')
ORDER BY ${orders}
ASC
DESC
limit #{size} offset #{offset}

select drug_id, drug_name as name, price, quantity, specifications, d.type_name as type, usage1, dosage, manufacturer, expiration_date, symptoms, notes,d.create_time, d.update_time from drugs join drugs_relation d on drugs.type_id = d.type_id
AND drugs.drug_name LIKE CONCAT('%', #{name}, '%') and d.relation_type = 1
AND d.type_name LIKE CONCAT('%', #{type}, '%') and d.relation_type = 1
AND drugs.drug_id LIKE CONCAT('%', #{id}, '%')
and drugs.create_time between #{startTime} and #{endTime}
ORDER BY ${orders}
ASC
DESC
limit #{size} offset #{offset}
